function gcd(a: number, b: number): number {
  // The Euclidean algorithm iteratively computes the GCD of two numbers.
  // It's based on the principle that gcd(a, b) = gcd(b, a % b).
  while (b) {
    // Loop continues as long as 'b' is not zero.
    const temp = b;
    // Store the current value of 'b' in 'temp' to use it later.
    b = a % b;
    // Calculate the remainder when 'a' is divided by 'b' and assign it to 'b'.
    // This is the core step that reduces the numbers towards their GCD.
    a = temp;
    // Assign the original value of 'b' (stored in 'temp') to 'a'.
    // Effectively, 'a' becomes the previous 'b', and 'b' becomes the remainder.
  }
  // When 'b' becomes 0, 'a' holds the GCD.
  return a;
  // Return the GCD.
}

