        while (b != 0) {
            // Store the value of b in a temporary variable
            int temp = b;
            // Calculate the remainder of a divided by b, and update b with this remainder
            // This is the key step in the Euclidean algorithm
            b = a % b;
            // Update a with the original value of b (which is stored in temp)
            a = temp;
        }
        // When b becomes 0, a contains the GCD
        return a;
    }
};

