function sieveOfEratosthenes(n: number): number[] {
  // Create a boolean array "isPrime[0..n]" and initialize
  // all entries it as true. A value in isPrime[i] will
  // finally be false if i is Not a prime, else true.
  const isPrime = new Array(n + 1).fill(true);

  // 0 and 1 are not prime numbers, so set isPrime[0] and isPrime[1] to false
  isPrime[0] = isPrime[1] = false;

  // Loop from 2 to the square root of n.
  // We only need to go up to the square root because if a number 'n'
  // is not prime, it must have a factor less than or equal to its square root.
  for (let i = 2; i * i <= n; i++) {
    // If isPrime[i] is still true, then it is a prime
    if (isPrime[i]) {
      // Update all multiples of i starting from i*i.
      // We start from i*i because all smaller multiples would have already been marked.
      for (let j = i * i; j <= n; j += i) {
        // Mark j as not prime
        isPrime[j] = false;
      }
    }
  }

  // Create an array to store prime numbers
  const primes: number[] = []; 
  // Iterate from 2 to n and add the prime numbers to the primes array
  for (let i = 2; i <= n; i++) {
    // If isPrime[i] is true, then i is a prime number
    if (isPrime[i]) primes.push(i);
  }

  // Return the array of prime numbers
  return primes;
}

