function modularExponentiation(base: number, exponent: number, modulus: number): number {
  if (modulus === 1) return 0;  // Edge case: anything mod 1 is 0

  let result: number = 1; // Initialize result to 1. This will accumulate the modular exponentiation.
  base = base % modulus; // Update base if it is greater than or equal to modulus.  This keeps the base within the modulus range.

  while (exponent > 0) { // Iterate while the exponent is greater than 0.
    // If exponent is odd, multiply base with result
    if (exponent % 2 === 1) { // Check if the exponent is odd.
      result = (result * base) % modulus; // If odd, multiply result with the base modulo modulus.
    }

    // exponent must be even now
    exponent = Math.floor(exponent / 2); // Divide the exponent by 2 (integer division). This is equivalent to a right bit shift.
    base = (base * base) % modulus; // Square the base modulo modulus. This efficiently calculates higher powers of the base.
  }
  return result; // Return the final result.
}

