function karatsuba(x: number, y: number): number {
  // Convert the numbers to strings for easier digit manipulation
  const xStr = x.toString();
  const yStr = y.toString();

  // Determine the maximum length of the two numbers
  const n = Math.max(xStr.length, yStr.length);

  // Base case: if the numbers are single digits, multiply them directly
  if (n <= 1) {
    return x * y;
  }

  // Calculate half of the maximum length, used for splitting the numbers
  const halfN = Math.floor(n / 2);

  // Split x into two parts: a (most significant digits) and b (least significant digits)
  const a = parseInt(xStr.slice(0, xStr.length - halfN) || '0');
  const b = parseInt(xStr.slice(xStr.length - halfN) || '0');
// Split y into two parts: c (most significant digits) and d (least significant digits)
  const c = parseInt(yStr.slice(0, yStr.length - halfN) || '0');
  const d = parseInt(yStr.slice(yStr.length - halfN) || '0');

  // Recursively compute the products ac, bd, and (a+b)(c+d)
  const ac = karatsuba(a, c);
  const bd = karatsuba(b, d);
  const ad_plus_bc = karatsuba(a + b, c + d) - ac - bd;

  // Combine the results to get the final product using the Karatsuba formula
  const result = ac * Math.pow(10, 2 * halfN) + ad_plus_bc * Math.pow(10, halfN) + bd;

  // Return the final product
  return result;
}

