class Solution {
public:

long long karatsuba(long long x, long long y) {
    // Base case: If either number is a single digit, perform standard multiplication.
    if (x < 10 || y < 10) {
        return x * y;
    }

    // Calculate the maximum number of digits in x or y.
    int n = max(to_string(x).length(), to_string(y).length());

    // Determine the split point (approximately half the digits).
    int m = n / 2;

    // Calculate 10^m, which will be used to split the numbers.
    long long power = 1;
    for (int i = 0; i < m; i++) power *= 10;

    // Split x and y into two parts: a, b, c, and d, such that x = a * 10^m + b and y = c * 10^m + d.
    long long a = x / power; // Most significant digits of x.
    long long b = x % power; // Least significant digits of x.
    long long c = y / power; // Most significant digits of y.
    long long d = y % power; // Least significant digits of y.

    // Recursively compute the three products: ac, bd, and (a+b)(c+d).
    long long ac = karatsuba(a, c); // Product of the most significant digits.
    long long bd = karatsuba(b, d); // Product of the least significant digits.

    // Calculate ad + bc using the identity: (a+b)(c+d) = ac + ad + bc + bd, thus ad + bc = (a+b)(c+d) - ac - bd.
    long long adbc = karatsuba(a + b, c + d) - ac - bd;

    // Combine the results to obtain the final product: x * y = ac * 10^(2m) + (ad + bc) * 10^m + bd.
    long long power2m = power * power; //10^(2m)
    return ac * power2m + adbc * power + bd;
}

};

