function solution(nums: number[], left: number, right: number): number {
  // Get the length of the input array.
  const n = nums.length;

  // Initialize the segment tree array with a size of 4*n (standard segment tree size).
  // Fill it with initial value of 0.
  const tree = new Array<number>(4 * n).fill(0);

  // Build the segment tree from the input array.
  buildTree(tree, nums, 0, 0, n - 1);

  // Query the segment tree for the sum in the range [left, right].
  return queryTree(tree, 0, 0, n - 1, left, right);
}

/**
 * Builds the segment tree recursively.
 * @param tree The segment tree array.
 * @param nums The input array.
 * @param node The current node index in the segment tree.
 * @param start The start index of the current segment in the input array.
 * @param end The end index of the current segment in the input array.
 */
function buildTree(
  tree: number[],
  nums: number[],
  node: number,
  start: number,
  end: number
): void {
  // Base case: If the segment contains only one element.
  if (start === end) {
    // Store the value of the element in the corresponding node of the tree.
    tree[node] = nums[start];
    return;
  }

  // Calculate the middle index of the current segment.
  const mid = Math.floor((start + end) / 2);

  // Recursively build the left subtree.
  buildTree(tree, nums, 2 * node + 1, start, mid);

  // Recursively build the right subtree.
  buildTree(tree, nums, 2 * node + 2, mid + 1, end);

  // The value of the current node is the sum of its children.
  tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
}

/**
 * Queries the segment tree for the sum in the range [left, right].
 * @param tree The segment tree array.
 * @param node The current node index in the segment tree.
 * @param start The start index of the current segment in the input array.
 * @param end The end index of the current segment in the input array.
 * @param left The left index of the query range.
 * @param right The right index of the query range.
 * @returns The sum of the elements in the range [left, right].
 */
function queryTree(
  tree: number[],
  node: number,
  start: number,
  end: number,
  left: number,
  right: number
): number {
  // If the query range is completely outside the current segment, return 0.
  if (left > end || right < start) return 0;

  // If the query range completely covers the current segment, return the value of the current node.
  if (left <= start && end <= right) return tree[node];

  // Calculate the middle index of the current segment.
  const mid = Math.floor((start + end) / 2);

  // Recursively query the left and right subtrees.
  const p1 = queryTree(tree, 2 * node + 1, start, mid, left, right);
  const p2 = queryTree(tree, 2 * node + 2, mid + 1, end, left, right);

  // Return the sum of the results from the left and right subtrees.
  return p1 + p2;
}

