        // j is the largest power of 2 that is less than or equal to the length of the query range (R - L + 1).
        int j = log[R - L + 1];

        // The minimum value in the range [L, R] is the minimum of the minimum value in the range [L, L + 2^j - 1] and the minimum value in the range [R - 2^j + 1, R].
        return min(st[L][j], st[R - (1 << j) + 1][j]);
