        // it means we can extend the previous longest prefix suffix.
        if (pattern[i] == pattern[len]) {
            lps[i++] = ++len; // Update LPS value and increment both 'i' and 'len'.
        } else {
            // If there is a mismatch, we check if 'len' is not 0.
            if (len != 0) {
                // If 'len' is not 0, it means we can fall back to the previous longest prefix suffix.
                // This is done by updating 'len' to the value stored in lps[len - 1].
                len = lps[len - 1];
            } else {
                // If 'len' is 0, it means there is no prefix suffix to fall back to.
                // In this case, we set lps[i] to 0 and move to the next character.
                lps[i++] = 0;
            }
        }
    }

    // Return the computed LPS array.
    return lps;
